use ferroui_base::{BoxedValue, FerroObject, FerroProperty, StyledProperty};
use ferroui_base::data::BindingPriority;
use ferroui_base::reactive::{IObserver, LightweightSubject, Observable};
use std::hint::black_box;
use std::rc::Rc;
use std::time::Instant;

#[repr(C)]
struct Timespec { seconds: i64, nanos: i64 }

unsafe extern "C" { fn clock_gettime(id: i32, timestamp: *mut Timespec) -> i32; }

pub(crate) fn thread_cpu_ns() -> i64 {
    let mut timestamp = Timespec { seconds: 0, nanos: 0 };
    assert_eq!(unsafe { clock_gettime(3, &mut timestamp) }, 0);
    timestamp.seconds * 1_000_000_000 + timestamp.nanos
}

#[derive(Copy,Clone)]
enum Mode { Notify, Install }

fn sample(host: &FerroObject, property: &'static StyledProperty<i32>, priority: BindingPriority,
          mode: Mode, count: usize) -> (i64,i64,u128) {
    let pool: [BoxedValue; 2] = [Rc::new(3), Rc::new(17)];
    let inputs = [Observable::single_value(pool[0].clone()), Observable::single_value(pool[1].clone())];
    let feed = Rc::new(LightweightSubject::<BoxedValue>::new());
    let binding = match mode {
        Mode::Notify => Some(host.bind_property_untyped(property, feed.clone(), priority)),
        Mode::Install => None,
    };
    let mut checksum = 0i64;
    let wall = Instant::now();
    let start = thread_cpu_ns();
    match mode {
        Mode::Notify => for i in 0..count {
            feed.on_next(black_box(&pool[i & 1]).clone());
            checksum += black_box(host.get_value(property)) as i64;
        },
        Mode::Install => for i in 0..count {
            let lease = host.bind_property_untyped(property, black_box(&inputs[i & 1]).clone(), priority);
            checksum += black_box(host.get_value(property)) as i64;
            lease.dispose();
        },
    }
    let ns = thread_cpu_ns() - start;
    let wall = wall.elapsed().as_nanos();
    if let Some(binding) = binding { binding.dispose(); }
    assert_eq!(checksum, 10*count as i64);
    assert_eq!(host.get_value(property), 1);
    (checksum, ns, wall)
}

#[test]
#[ignore]
fn profile_boxed_binding() {
    let host = FerroObject::new();
    let property = FerroProperty::register::<FerroObject,_>("BoxedProbe", 1);
    let lanes = [
        ("local_notify", BindingPriority::LocalValue, Mode::Notify, 40000),
        ("style_notify", BindingPriority::Style, Mode::Notify, 40000),
        ("local_install", BindingPriority::LocalValue, Mode::Install, 12000),
        ("style_install", BindingPriority::Style, Mode::Install, 12000),
    ];
    let round = std::env::var("BINDING_ROUND").unwrap_or_default().parse::<usize>().unwrap_or_default();
    let typed = ["typed_notify", "typed_writeback", "typed_context"];
    let total = lanes.len() + typed.len();
    for i in 0..total {
        let index = (i + round) % total;
        if index >= lanes.len() {
            let name = typed[index - lanes.len()];
            crate::typed_cases::sample(name, 400);
            let n = 12000;
            let (sum, cpu, wall) = crate::typed_cases::sample(name, n);
            println!("BOXED {name} {n} {sum} {cpu} {wall}");
            continue;
        }
        let (name, priority, mode, n)=lanes[index];
        sample(&host, property, priority, mode, n / 20);
        let (sum, cpu, wall) = sample(&host, property, priority, mode, n);
        println!("BOXED {name} {n} {sum} {cpu} {wall}");
    }
}

