use crate::test_root::TestRoot;


pub(crate) fn sample(lane: &str, count: usize) -> (i64, i64, u128) {
    use std::hint::black_box;
    use std::time::Instant;
    let a = ViewModel::with_string("A");
    let b = ViewModel::with_string("B");
    let target = create_target(Some(&a), BindingMode::TwoWay);
    let initial = a.string_value_set_count.get();
    let mut checksum = 0i64;
    let wall = Instant::now();
    let start = crate::boxed_timing::thread_cpu_ns();
    match lane {
        "typed_notify" => for i in 0..count {
            a.set_string_value(Some(s(if i % 2 == 0 { "B" } else { "A" })));
            checksum += black_box(target.text().unwrap()).as_bytes()[0] as i64;
        },
        "typed_writeback" => for i in 0..count {
            target.set_text(Some(if i % 2 == 0 { "B" } else { "A" }));
            checksum += black_box(a.string_value().unwrap()).as_bytes()[0] as i64;
        },
        "typed_context" => for i in 0..count {
            target.set_data_context(Some(if i % 2 == 0 { b.clone() } else { a.clone() }));
            checksum += black_box(target.text().unwrap()).as_bytes()[0] as i64;
        },
        _ => unreachable!(),
    }
    let cpu = crate::boxed_timing::thread_cpu_ns() - start;
    let wall = wall.elapsed().as_nanos();
    assert_eq!(checksum, (65 + 66) * count as i64 / 2);
    assert_eq!(target.text().as_deref(), Some("A"));
    assert_eq!(a.string_value().as_deref(), Some("A"));
    assert_eq!(a.property_changed_subscription_count(), 1);
    assert_eq!(b.property_changed_subscription_count(), 0);
    let expected = if lane == "typed_context" { 0 } else { count as i32 };
    assert_eq!(a.string_value_set_count.get() - initial, expected);
    (checksum, cpu, wall)

